Вот простой калькулятор на Python:

```python
def calculate(a, op, b):
    if op == "+":
        return a + b
    if op == "-":
        return a - b
    if op == "*":
        return a * b
    if op == "/":
        if b == 0:
            raise ZeroDivisionError("деление на ноль")
        return a / b
    if op == "**":
        return a ** b
    raise ValueError(f"неизвестная операция: {op}")


def main():
    print("Калькулятор. Операции: + - * / **. Выход — 'q'.")

    while True:
        line = input("> ").strip()
        if line.lower() in ("q", "quit", "exit"):
            break

        parts = line.split()
        if len(parts) != 3:
            print("Формат: число операция число (например: 2 + 3)")
            continue

        try:
            a = float(parts[0])
            b = float(parts[2])
            result = calculate(a, parts[1], b)
            print(result)
        except ValueError as e:
            print("Ошибка:", e)
        except ZeroDivisionError:
            print("Ошибка: деление на ноль")


if __name__ == "__main__":
    main()
```

